action.new_str:
async function complete(job: ClaimedJob<ReceiptJob>): Promise<void> {
  const erased = await isCustomerErased(job.merchant_id, job.payload.customerId);
  const payload = erased
    ? { ...job.payload, customerSnapshot: anonymizedCustomerSnapshot(job.payload.customerId) }
    : job.payload;
  const stored = await storeReceipt(payload);

